1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isWithinOneStep = (coordinate: number, other: number): boolean =>
7	  Math.abs(coordinate - other) <= 1;
8	
9	const isNeighbor = (cell: Cell, other: Cell): boolean =>
10	  isWithinOneStep(cell[0], other[0]) &&
11	  isWithinOneStep(cell[1], other[1]) &&
12	  !isSameCell(cell, other);
13	
14	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
15	  liveCells.filter((other) => isNeighbor(cell, other)).length;
16	
17	const survives = (neighborCount: number): boolean =>
18	  neighborCount === 2 || neighborCount === 3;
19	
20	export function nextGeneration(liveCells: Cell[]): Cell[] {
21	  return liveCells.filter((cell) =>
22	    survives(countLiveNeighbors(cell, liveCells)),
23	  );
24	}
