const isNeighbor = (cell: Cell, other: Cell): boolean => {
  const [x, y] = cell;
  const [otherX, otherY] = other;
  return (
    isWithinOneStep(x, otherX) &&
    isWithinOneStep(y, otherY) &&
    !isSameCell(cell, other)
  );
};
